ALTER TABLE "system_settings" ALTER COLUMN "light_palette" SET DEFAULT '{"background":"#f8faf8","surface":"#ffffff","text":"#14221d","muted":"#66756e","primary":"#087f5b","primaryText":"#ffffff","serviceStatusText":"#087f5b","border":"#dfe7e2","success":"#15946c","warning":"#d49b28","danger":"#c85148"}'::jsonb;--> statement-breakpoint
ALTER TABLE "system_settings" ALTER COLUMN "dark_palette" SET DEFAULT '{"background":"#0d1512","surface":"#15201b","text":"#eef6f1","muted":"#9caea5","primary":"#45c795","primaryText":"#07110d","serviceStatusText":"#45c795","border":"#2a3a33","success":"#45c795","warning":"#e1ad45","danger":"#ef7770"}'::jsonb;--> statement-breakpoint
UPDATE "system_settings" SET "light_palette" = jsonb_set("light_palette", '{serviceStatusText}', "light_palette" -> 'primary') WHERE NOT ("light_palette" ? 'serviceStatusText');--> statement-breakpoint
UPDATE "system_settings" SET "dark_palette" = jsonb_set("dark_palette", '{serviceStatusText}', "dark_palette" -> 'primary') WHERE NOT ("dark_palette" ? 'serviceStatusText');
